/// The number of properties of the tree.
const NPROPS: usize = count_props(&ROOT);
/// The property names in the order dtc meets them (depth first, properties first).
const NAMES: [&str; NPROPS] = {
    let mut names = [""; NPROPS];
    collect_names(&ROOT, &mut names, 0);
    names
};
/// The structure block's size: the tree and `FDT_END`.
const DT_STRUCT_SIZE: usize = node_size(&ROOT) + 4;
/// The strings block's size: each name once, NUL-terminated.
const DT_STRINGS_SIZE: usize = strings_size();
/// The structure block's offset.
const DT_STRUCT_OFF: usize = DT_HEADER_SIZE + DT_RSVMAP_SIZE;
/// The strings block's offset.
const DT_STRINGS_OFF: usize = DT_STRUCT_OFF + DT_STRUCT_SIZE;
/// `_dt_blob_abs_end - _dt_blob_start`: the blob and its padding.
pub const DT_BLOB_SIZE: usize = DT_STRINGS_OFF + DT_STRINGS_SIZE + DT_PAD;

/// The blob's bytes as dtc writes them (the tests work on copies).
#[cfg(test)]
pub static DT_BLOB_TEMPLATE: [u8; DT_BLOB_SIZE] = build();

/// The blob, aligned for the word reads of the tree code.
#[repr(C, align(8))]
pub struct DtBlob(pub [u8; DT_BLOB_SIZE]);

/// A blob being written: the bytes and the write position.
struct Writer {
    buf: [u8; DT_BLOB_SIZE],
    pos: usize,
}

impl Writer {
    /// `.byte`.
    const fn byte(&mut self, b: u8) {
        self.buf[self.pos] = b;
        self.pos += 1;
    }

    /// A big-endian word.
    const fn be32(&mut self, v: u32) {
        let b = v.to_be_bytes();
        let mut i = 0;
        while i < 4 {
            self.byte(b[i]);
            i += 1;
        }
    }

    /// `.asciz`.
    const fn asciz(&mut self, s: &str) {
        let b = s.as_bytes();
        let mut i = 0;
        while i < b.len() {
            self.byte(b[i]);
            i += 1;
        }
        self.byte(0);
    }

    /// `.balign 4, 0`.
    const fn balign4(&mut self) {
        while !self.pos.is_multiple_of(4) {
            self.byte(0);
        }
    }

    /// A node, its properties and its children.
    const fn node(&mut self, n: &Node) {
        self.be32(FDT_NODE_BEGIN);
        self.asciz(n.name);
        self.balign4();
        let mut i = 0;
        while i < n.props.len() {
            let p = &n.props[i];
            self.be32(FDT_PROPERTY);
            self.be32(value_size(&p.value) as u32);
            self.be32(name_offset(p.name) as u32);
            match p.value {
                Value::Empty => {}
                Value::Cells(c) => {
                    let mut j = 0;
                    while j < c.len() {
                        self.be32(c[j]);
                        j += 1;
                    }
                }
                Value::Strings(s) => {
                    let mut j = 0;
                    while j < s.len() {
                        self.asciz(s[j]);
                        j += 1;
                    }
                }
            }
            self.balign4();
            i += 1;
        }
        let mut i = 0;
        while i < n.children.len() {
            self.node(&n.children[i]);
            i += 1;
        }
        self.be32(FDT_NODE_END);
    }
}

/// `dt_blob_start`: the blob, which `efi_acpi` edits in place.
pub static DT_BLOB: StaticCell<DtBlob> = StaticCell::new(DtBlob(build()));

/// `const` string equality.
const fn str_eq(a: &str, b: &str) -> bool {
    let (a, b) = (a.as_bytes(), b.as_bytes());
    if a.len() != b.len() {
        return false;
    }
    let mut i = 0;
    while i < a.len() {
        if a[i] != b[i] {
            return false;
        }
        i += 1;
    }
    true
}

/// The properties of `n` and its descendants.
const fn count_props(n: &Node) -> usize {
    let mut count = n.props.len();
    let mut i = 0;
    while i < n.children.len() {
        count += count_props(&n.children[i]);
        i += 1;
    }
    count
}

/// Writes the property names of `n` and its descendants into `names` from `at`; the next
/// free index.
const fn collect_names(n: &Node, names: &mut [&'static str; NPROPS], at: usize) -> usize {
    let mut at = at;
    let mut i = 0;
    while i < n.props.len() {
        names[at] = n.props[i].name;
        at += 1;
        i += 1;
    }
    let mut i = 0;
    while i < n.children.len() {
        at = collect_names(&n.children[i], names, at);
        i += 1;
    }
    at
}

/// The index of the first use of `name` in [`NAMES`].
const fn first_use(name: &str) -> usize {
    let mut i = 0;
    while i < NPROPS {
        if str_eq(NAMES[i], name) {
            return i;
        }
        i += 1;
    }
    NPROPS
}

/// The offset of `name` in the strings block.
const fn name_offset(name: &str) -> usize {
    let first = first_use(name);
    let mut off = 0;
    let mut i = 0;
    while i < first {
        if first_use(NAMES[i]) == i {
            off += NAMES[i].len() + 1;
        }
        i += 1;
    }
    off
}

/// The strings block's size.
const fn strings_size() -> usize {
    let mut size = 0;
    let mut i = 0;
    while i < NPROPS {
        if first_use(NAMES[i]) == i {
            size += NAMES[i].len() + 1;
        }
        i += 1;
    }
    size
}

/// The size of a property's value.
const fn value_size(v: &Value) -> usize {
    match v {
        Value::Empty => 0,
        Value::Cells(c) => 4 * c.len(),
        Value::Strings(s) => {
            let mut size = 0;
            let mut i = 0;
            while i < s.len() {
                size += s[i].len() + 1;
                i += 1;
            }
            size
        }
    }
}

/// `n`'s size in the structure block.
const fn node_size(n: &Node) -> usize {
    let mut size = 4 + (n.name.len() + 1).div_ceil(4) * 4;
    let mut i = 0;
    while i < n.props.len() {
        size += 12 + value_size(&n.props[i].value).div_ceil(4) * 4;
        i += 1;
    }
    let mut i = 0;
    while i < n.children.len() {
        size += node_size(&n.children[i]);
        i += 1;
    }
    size + 4
}

/// The blob, as dtc lays it out.
const fn build() -> [u8; DT_BLOB_SIZE] {
    let mut w = Writer {
        buf: [0; DT_BLOB_SIZE],
        pos: 0,
    };

    // header
    w.be32(FDT_MAGIC);
    w.be32(DT_BLOB_SIZE as u32); // totalsize
    w.be32(DT_STRUCT_OFF as u32); // off_dt_struct
    w.be32(DT_STRINGS_OFF as u32); // off_dt_strings
    w.be32(DT_HEADER_SIZE as u32); // off_mem_rsvmap
    w.be32(DT_VERSION); // version
    w.be32(DT_LAST_COMP_VERSION); // last_comp_version
    w.be32(0); // boot_cpuid_phys
    w.be32(DT_STRINGS_SIZE as u32); // size_dt_strings
    w.be32(DT_STRUCT_SIZE as u32); // size_dt_struct

    // Memory reserve map from source file: the terminating entry
    w.pos += DT_RSVMAP_SIZE;

    w.node(&ROOT);
    w.be32(FDT_END);

    let mut i = 0;
    while i < NPROPS {
        if first_use(NAMES[i]) == i {
            w.asciz(NAMES[i]);
        }
        i += 1;
    }

    // the padding stays zero
    w.buf
}

/// `dt_blob_start`.
pub fn dt_blob_start() -> *mut u8 {
    DT_BLOB.as_ptr().cast()
}

const _: () = assert!(DT_STRUCT_OFF.is_multiple_of(8));
